source('./analyses/robustness/scripts/common.R')
suppressPackageStartupMessages(library(OmicSelector));stopifnot(as.character(packageVersion('OmicSelector'))=='2.6.9')
record(file.path(M,'cohort_inventory/out/OmicSelector_2.6.9.tar.gz'))
q<-rr(file.path(ROOT,'analysis/reassay_casemix/prepared/GSE71008.rds'));sp<-rr(file.path(ROOT,'analysis/reassay_casemix/prepared/GSE71008_split1.rds'))
X<-q$mats[['1']];lookup<-fread(record(file.path(B,'library/OmicSelector/extdata/mimat_hsa_lookup_v22_1.tsv')),skip=1);nm<-lookup$hsa_mir_name[match(colnames(X),lookup$mimat_id)];stopifnot(!anyNA(nm),!anyDuplicated(nm));colnames(X)<-nm;tr<-sp$tr;te<-sp$te;stopifnot(!length(intersect(tr,te)))
prep<-fit_singlesample_preprocessor(X[tr,,drop=FALSE],type='counts',scale='cpm',features=colnames(X))
rows<-list();ev<-list();held<-te[1]; specimen<-rownames(X)[held];y<-q$meta$outcome
for(method in c('reo-ktsp','reo-pairratio','ws-rclr-trimmed','ws-balance-ilr')){
 set.seed(202610262L);dep<-deploy_singlesample(X[tr,,drop=FALSE],y[tr],method=method,preprocessor=prep,verify=TRUE)
 req<-OmicSelector:::`.ss_required_features`(dep$model);background<-setdiff(colnames(X),req)[1];missing<-req[1];base<-X[held,,drop=FALSE]
 cutoff_fun<-function(s,y){cuts<-c(-Inf,sort(unique(s)),Inf);cuts[which.max(vapply(cuts,function(cut)mean(s[y==1]>=cut)+mean(s[y==0]<cut)-1,0.))]}
 cutoff<-cutoff_fun(as.numeric(score_specimen(dep,X[tr,,drop=FALSE],detected=X[tr,,drop=FALSE]>0)),y[tr])
 extras<-matrix(c(1e8,1e10,1e12),1,3,dimnames=list(rownames(base),paste0('EXTRA_BACKGROUND_',1:3)))
 cases<-list(complete=base,extra_background=cbind(base,extras),missing_required=base[,setdiff(colnames(base),missing),drop=FALSE],missing_background=base[,setdiff(colnames(base),background),drop=FALSE],all_zero_nondetect=base*0,positive_floor_all_nondetect=base*0+1)
 rawdep<-dep;rawdep$preprocessor<-NULL
 for(route in c('frozen_preprocessor','prepared_abundance_direct'))for(cond in names(cases))for(strict in c(FALSE,TRUE)){
  raw<-cases[[cond]];mask<-raw>0;if(cond=='positive_floor_all_nondetect')mask[,]<-FALSE
  if(route=='frozen_preprocessor'){inp<-raw;det<-mask;d<-dep;processed<-apply_singlesample_preprocessor(prep,raw)$abundance}
  else {d<-rawdep;inp<-apply_singlesample_preprocessor(prep,raw)$abundance;if(cond=='extra_background')inp<-cbind(inp,extras);det<-inp>0;if(cond=='positive_floor_all_nondetect')det[,]<-FALSE;processed<-inp}
  msgs<-warn<-character();code<-'';error<-'';support<-'';score<-NA_real_
  ans<-tryCatch(withCallingHandlers(score_specimen(d,inp,detected=det,strict=strict),warning=function(w){warn<<-c(warn,conditionMessage(w));invokeRestart('muffleWarning')},message=function(m){msgs<<-c(msgs,conditionMessage(m));invokeRestart('muffleMessage')}),error=function(e){code<<-if(is.null(e$code))'UNCODED_ERROR'else e$code;error<<-conditionMessage(e);NULL})
  if(!is.null(ans)){score<-as.numeric(ans);support<-paste(capture.output(print(attr(ans,'support'))),collapse=' ')}
  rows[[length(rows)+1]]<-data.table(dataset='GSE71008',specimen,replicate='1',training_n=length(tr),held_out=TRUE,scorer=method,route,condition=cond,strict,strict_supported=TRUE,frozen_universe_n=ncol(X),input_n=ncol(inp),post_conversion_n=ncol(processed),removed_feature=if(cond=='missing_required')missing else if(cond=='missing_background')background else'',score,threshold=cutoff,call=if(is.finite(score))score>=cutoff else NA,refused=is.null(ans),code,error,warnings=paste(warn,collapse='; '),messages=paste(msgs,collapse='; '),support,mask_aligned=identical(dimnames(inp),dimnames(det)),computing_host=HOST,device='CPU',threads=1L,package_version='2.6.9',tarball_sha256='5bc289307aaa008cc46c0ee6724325eda415be46bdc59c9108545267d7eb92cd')
 }
 saveRDS(dep,file.path(B,'work',switch(as.character(method),'ALL_NONDETECT'='assay_transfer_ALL_NONDETECT.rds','CPU'='assay_transfer_CPU.rds','EXTRA_BACKGROUND_'='assay_transfer_EXTRA_BACKGROUND_.rds','GSE71008'='assay_transfer_GSE71008.rds','OmicSelector'='assay_transfer_OmicSelector.rds','UNCODED_ERROR'='assay_transfer_UNCODED_ERROR.rds','aligned_masks'='assay_transfer_aligned_masks.rds','all_nondetect_refused'='assay_transfer_all_nondetect_refused.rds','all_zero_nondetect'='assay_transfer_all_zero_nondetect.rds','complete'='assay_transfer_complete.rds','counts'='assay_transfer_counts.rds','cpm'='assay_transfer_cpm.rds','extra_background'='assay_transfer_extra_background.rds','extra_columns_dropped_by_frozen_preprocessor'='assay_transfer_extra_columns_dropped_by_frozen_preprocessor.rds','frozen_preprocessor'='assay_transfer_frozen_preprocessor.rds','assay_transfer'='assay_transfer_assay_transfer.rds','assay_transfer_'='assay_transfer_assay_transfer_.rds','missing_background'='assay_transfer_missing_background.rds','missing_required'='assay_transfer_missing_required.rds','muffleMessage'='assay_transfer_muffleMessage.rds','muffleWarning'='assay_transfer_muffleWarning.rds','positive_floor_all_nondetect'='assay_transfer_positive_floor_all_nondetect.rds','prepared_abundance_direct'='assay_transfer_prepared_abundance_direct.rds','route'='assay_transfer_route.rds','scorer'='assay_transfer_scorer.rds','strict'='assay_transfer_strict.rds','strict_missing_required_refused'='assay_transfer_strict_missing_required_refused.rds','support'='assay_transfer_support.rds','work'='assay_transfer_work.rds',paste0('assay_transfer_',method,'.rds'))))
}
z<-rbindlist(rows);base<-z[condition=='complete',.(scorer,route,strict,base_score=score,base_call=call)];z<-merge(z,base,by=c('scorer','route','strict'));z[,`:=`(score_difference=score-base_score,changed_call=call!=base_call)]
stopifnot(all(z$mask_aligned),all(z[route=='frozen_preprocessor'&condition=='extra_background',score_difference==0]),all(z[condition%in%c('all_zero_nondetect','positive_floor_all_nondetect'),refused&code=='ALL_NONDETECT']),all(z[strict&condition=='missing_required',refused]))
wr(z,'item6_assay_assay_transfer.tsv');wr(data.table(check=c('aligned_masks','extra_columns_dropped_by_frozen_preprocessor','all_nondetect_refused','strict_missing_required_refused'),pass=TRUE),'evidence/assay_transfer_checks.tsv');finish('handoff')
